demo.css:
/* Only for the preview: the messages sit in the corner of the box, as
		   they sit in the corner of the window in an app. The height gives them
		   room. */
		.surface { min-block-size: 10rem; }

/* Your own classes. These two rules are all it takes. */
.case-last-line {
  inline-size: 70%;
}

.case-image {
  --lt-skeleton-height: var(--lt-spacing-12);
}

/* Only for the preview: the bar sits at the top of the box, as it sits
		   at the top of the window in an app. The space here keeps it from
		   covering the buttons. A consumer needs none of this. */
		.surface { padding-block-start: var(--lt-spacing-12); }

/* The bubble sits above the trigger, and needs some space in this box
       so it is not clipped. In a real page the space on the page decides. */
    .lt-tooltip { margin-block-start: var(--lt-spacing-8); }

accessibility.code:
@media (forced-colors: active) {
	.my-selected-row {
		background-color: Highlight;
		color: HighlightText;
	}
}

